import re
from dataclasses import dataclass

from .csvio import iter_rows
from .errors import LedgerError

_PRIORITY = re.compile(r"-?[0-9]+")


@dataclass(frozen=True)
class Rule:
    category: str
    type: str
    pattern: str
    priority: int
    compiled: "re.Pattern[str] | None" = None


def load_rules(path: str) -> list[Rule]:
    out = []
    for line, row in iter_rows(path, ["category", "type", "pattern", "priority"], 4):
        def fail(msg):
            return LedgerError(4, f"{path}:{line}: {msg}")

        category = row["category"].strip()
        if not category:
            raise fail("empty category")
        typ = row["type"].strip()
        if typ not in ("contains", "regex"):
            raise fail(f"invalid type '{typ}'")
        pattern = row["pattern"].strip()
        if not pattern:
            raise fail("empty pattern")
        prio = row["priority"].strip()
        try:
            if not _PRIORITY.fullmatch(prio):
                raise ValueError
            priority = int(prio)
        except ValueError:
            raise fail(f"invalid priority '{prio}'") from None
        compiled = None
        if typ == "regex":
            try:
                compiled = re.compile(pattern, re.IGNORECASE)
            except (re.error, RecursionError, OverflowError):
                raise fail(f"invalid regex '{pattern}'") from None
        out.append(Rule(category, typ, pattern, priority, compiled))
    return out


def categorize(description: str, rules: list[Rule]) -> str:
    ordered = sorted(enumerate(rules), key=lambda ir: (-ir[1].priority, ir[0]))
    folded = description.casefold()
    for _, r in ordered:
        if r.type == "contains":
            if r.pattern.casefold() in folded:
                return r.category
        elif r.compiled.search(description):
            return r.category
    return "Uncategorized"

